//! Real Feynman-100 recovery runner (M6, phop side).
//!
//! Loads every `*.csv` in a directory (generated by `scripts/gen_feynman.py`; last column = target),
//! runs the discoverer on each, and reports recovery (R² ≥ 0.999), R², MSE, complexity, and
//! wall-clock as CSV on stdout, plus a summary on stderr. The PySR side
//! (`scripts/pysr_feynman.py`) consumes the same CSVs, so the comparison is apples-to-apples.
//!
//! Usage: `cargo run -p phop-bench --release --bin feynman -- <csv_dir> [max_vars]`
//!
//! `max_vars` (default 8) skips equations with more input variables than that: phop's depth-3
//! enumerate blows up combinatorially at high arity (it OOM-crashes at 9 variables — Risk T3), and
//! such equations are unreachable for a shallow single-operator search anyway. Skipped equations are
//! reported as `skipped` (counted as not recovered).

use phop_bench::r2_score;
use phop_core::{eval_tree, Config, DataSet, Discoverer};
use std::path::PathBuf;
use std::time::Instant;

/// Recovery tolerance on R² (numeric "accuracy solution", matching the PySR side).
const R2_TOL: f64 = 0.999;
/// Default cap on input-variable count (phop's enumerate OOMs beyond this).
const DEFAULT_MAX_VARS: usize = 8;

fn main() {
    let dir = std::env::args().nth(1).unwrap_or_else(|| ".".to_string());
    let max_vars = std::env::args()
        .nth(2)
        .and_then(|s| s.parse::<usize>().ok())
        .unwrap_or(DEFAULT_MAX_VARS);
    let mut paths: Vec<PathBuf> = match std::fs::read_dir(&dir) {
        Ok(rd) => rd
            .filter_map(|e| e.ok().map(|e| e.path()))
            .filter(|p| p.extension().is_some_and(|x| x == "csv"))
            .collect(),
        Err(e) => {
            eprintln!("phop feynman: cannot read dir {dir}: {e}");
            std::process::exit(1);
        }
    };
    paths.sort();

    // Shallow-depth config (same spirit as the `recovery` bin).
    let cfg = Config::default()
        .max_depth(3)
        .max_epochs(300)
        .top_k(5)
        .seed(42);

    println!("name,recovered,r2,mse,complexity,ms");
    let mut recovered = 0usize;
    let mut total_ms = 0u128;
    let mut attempted = 0usize;

    for p in &paths {
        let name = p
            .file_stem()
            .map(|s| s.to_string_lossy().into_owned())
            .unwrap_or_else(|| "unknown".to_string());
        let ds = match DataSet::from_csv(p) {
            Ok(d) => d,
            Err(_) => {
                println!("{name},error,nan,inf,0,0");
                continue;
            }
        };
        if ds.n_vars() > max_vars {
            println!("{name},skipped,nan,inf,0,0");
            continue;
        }
        attempted += 1;
        let start = Instant::now();
        let outcome = Discoverer::new(cfg.clone()).fit(&ds);
        let ms = start.elapsed().as_millis();
        total_ms += ms;

        match outcome.ok().and_then(|f| f.best().cloned()) {
            Some(best) => {
                let r2 = match eval_tree(&best.tree, &ds.x) {
                    Ok(pred) => r2_score(&ds.y, &pred),
                    Err(_) => f64::NAN,
                };
                let is_rec = r2.is_finite() && r2 >= R2_TOL;
                if is_rec {
                    recovered += 1;
                }
                println!(
                    "{name},{is_rec},{r2:.6},{:.6e},{},{ms}",
                    best.mse, best.complexity
                );
            }
            None => println!("{name},false,nan,inf,0,{ms}"),
        }
    }

    eprintln!(
        "phop feynman: recovered {recovered}/{attempted} (R² ≥ {R2_TOL}) in {total_ms} ms total"
    );
}
